UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b3664-qL8Pw6KxKRCe.png', birthday = NULL, blood_type = NULL, voice_actor = '高山みなみ', height = NULL, description = '天道早雲の次女。彼女にとって最も大切なのはお金であり、それを手に入れるためなら、自分の家族を脅迫することさえ厭わない。 一部の物語では、金銭をゆすり取ろうとしたり、単なる自分の楽しみのために賭け事をしたりするなど、重要な役割を果たしている。彼女は皮肉屋で、物質主義的、利己的、 manipulative、サディスティック、そして完全に道徳観念に欠けた態度を持っており、姉とは鮮明な対照をなしている。実際、彼女は漫画と' WHERE character_id = 'CH013944';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b10028-gNNez97rQTTU.png', birthday = NULL, blood_type = NULL, voice_actor = '佐倉綾音', height = NULL, description = 'セント・バッカス女子学校の体操部のキャプテン。「ブラック・ローズ」と呼ばれているが、これはおそらく、高音の笑い声を響かせながら、渦巻くような黒いバラの跡を残して舞台から退場するという、彼女特有の劇的な演出に由来しているのだろう。  コダチは武術リズミック体操の専門家であり、アクロバットや、ボール、クラブ、ホップ、リボン、ロープを武器として使いこなすことに長けている。彼女は非常に機敏で、戦闘においては型破りな手段を用いることも厭わない。' WHERE character_id = 'CH013945';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b18771-UGhvBkYAWL54.png', birthday = NULL, blood_type = NULL, voice_actor = '森川智之', height = NULL, description = '小乃東風博士は地元のカイロプラクターで、あかねや乱馬が度重なる喧嘩で打撲や擦り傷、関節の脱臼を負った際、よく手当てをしてくれる。彼は武術の技に非常に詳しいが、実際に練習している姿は一度も見たことがない。 また、東風先生は天道かすみに深く恋をしている。実際、彼女の前にいると、眼鏡が曇って緊張してしまう。そのせいで、これまでかなりの数の患者を怪我させてしまったこともある。東風先生は地域で親しまれており、多くの年配の患者を抱えている。' WHERE character_id = 'CH013946';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b2369-Gok65en32hkE.png', birthday = NULL, blood_type = NULL, voice_actor = '山寺宏一', height = NULL, description = 'リョウガは、早乙女乱馬の永遠のライバルであり、友人でもある。乱馬が「真の友人」だと公言している唯一の人物であり、事実上の第三の主人公とも言える存在で、本作で最も強力な戦闘者の一人である。 リョウガの最も顕著な特徴は、両親（さらには家族全員）と同様に、方向感覚が全くないことだ。彼は正しい道を進むことができず、たとえその道が途中で曲がっていても、与えられた指示を文字通り忠実に守ろうとする傾向がある。彼は方向感覚に欠けており、' WHERE character_id = 'CH013947';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b9913-PZTlL3MZ2MF2.png', birthday = NULL, blood_type = NULL, voice_actor = 'チョー ', height = NULL, description = '早乙女玄馬は息子の乱馬によく似ている。武術の腕前に関しては少々傲慢なところがあるが、臆病さや怠惰のせいで、その実力をめったに見せることはない。乱馬を十仙京に連れて行ったのは玄馬だった。 中国語で書かれたパンフレットが読めなかったため、彼はそこに呪いが存在することなど全く知らなかった。冷たい水を浴びると、玄馬はパンダに変身する。この姿のときは、メッセージが書かれた看板を使って意思疎通を図る。彼はしばしば…' WHERE character_id = 'CH013948';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b32560-rIeRX9sWy1dC.png', birthday = NULL, blood_type = NULL, voice_actor = '宮野真守', height = NULL, description = 'あずさのスケートのパートナー。かなりの女たらしで、これまでに1000人以上の女性とキスをしており、しばしば他のフィギュアスケートのペアを破局に追い込んでいる。ミカドは時折、あずさを嫌っているようにも見え、周囲の人々が彼女に対して抱く苛立ちも理解している。あずさの子供っぽい振る舞いにしばしば腹を立てるが、そのせいで痛い目を見ることも多い。' WHERE character_id = 'CH013949';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b2374-lm7OuE44qwSz.jpg', birthday = NULL, blood_type = NULL, voice_actor = '名塚佳織', height = NULL, description = '10年前、地方での合宿中、玄馬は右京の父親のお好み焼き屋台を盗み、彼女を置き去りにして、彼女と父親との取り決めを破ってしまった。 しかし、その以前、乱馬と右京は友人同士だった。もっとも、乱馬は彼女が女の子だとは知らなかったのだが。 仲間たちから恥をかかされ、嘲笑された右京は、男の子を好きにならないと決心し、男の子のような服装をして生活し、お好み焼き流の武術に打ち込むようになった。激しい戦いの末、乱馬は彼女の本当の性別を知る。一方、' WHERE character_id = 'CH013950';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b9259-OAvdmTfWCinV.jpg', birthday = NULL, blood_type = NULL, voice_actor = '悠木碧', height = NULL, description = '白鳥あずさは、「コルホッツ高校の黄金のペア」の女性メンバーである。彼女は、自分が「かわいい」と思うものを収集し、それらに（たいていはフランス語由来の）名前をつけることに夢中になっていることでよく知られている。 「あずさ」は「カタルパの木」を意味し、「白鳥」は「白い鳥」を意味する。  あずさは非常に頭が悪く（久野の言葉を借りれば「半人前」）、このシリーズの基準からしても異様な存在だ。白鳥は窃盗癖があり、理由もなく無作為に物や人を持ち去りたくなる衝動に駆られる。' WHERE character_id = 'CH013951';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b17171-EyV1nYr4rWQK.jpg', birthday = NULL, blood_type = NULL, voice_actor = '井上和彦', height = NULL, description = 'ソンとゲンマは、若い頃、邪悪で変態的な八宝斎のもとで修行を積んだ。この小男こそが、「何でもありの武術」（無別格闘流）の真の達人である。また、彼は信じがたいほどのパンティ泥棒であり、好色家でもある。 修行の見返りとして、彼は意に反して弟子となった二人の少年を叱りつけたり甘言で誘惑したりして、自分のパンティ盗みや覗き行為を手伝わせた。その過程で、彼らはたいてい屈辱を味わったり怪我をしたりすることになった。ようやく修行を終えた（つまり、逃げ出した）後、彼らは' WHERE character_id = 'CH013952';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b3665-iOq3GT4AmVGB.jpg', birthday = NULL, blood_type = NULL, voice_actor = '井上喜久子', height = NULL, description = '天野家の長女で、姉妹の中で最も穏やかな性格だ。 高校を卒業した彼女は、母が若くして亡くなって以来、料理や掃除、家族の世話をしながら、天道家の「家長」の代わりとして、一日の大半を家の世話に費やしている。  かすみは、とても優しく、思いやりがあり、自己犠牲的な性格を持つ、完璧な女性として描かれている。おそらくその極めて愛らしい人柄ゆえに、彼女はほとんどの奇抜な出来事の影響をほとんど受けない。' WHERE character_id = 'CH013953';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b7699-qBXAtJitohG0.png', birthday = NULL, blood_type = NULL, voice_actor = '杉田智和', height = NULL, description = '九能帯刀は風林館高校の上級生で、少なくとも乱馬が現れるまでは、校内一の男として君臨していた。非常に裕福な家庭の出身であり、剣道部の部長も務めており、その富と剣を等しく自在に操る。 シェイクスピア風の詩を口にするのが好きで（日本語版では孔子の言葉を引用している）、あかねに狂おしいほど恋をしている。また、乱馬の女の姿にも心を奪われてしまうが、彼女が実は女の姿をした宿敵であることに気づくことは決してない。かつて彼は……' WHERE character_id = 'CH013954';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b9215-izlALwazVkxE.png', birthday = NULL, blood_type = NULL, voice_actor = '大塚明夫', height = NULL, description = 'ソンは天道家の当主であり、「何でもありの武術」を修める2つの家系のうちの1つを率いている。彼は妻を亡くした未亡人であり、3人の娘たちを独力で育てている。彼は広々とした道場を所有しているが、そこで繰り広げられる戦いのせいで、時折修繕が必要になることもある。 彼は自身の道場を所有しているが、生徒の姿は明確に描かれていない。地域住民の代表者が、異常現象に関する問題を抱えた際に頻繁に彼に相談に訪れるため、それが生徒の存在を示唆している可能性もある。また、彼は……' WHERE character_id = 'CH013955';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b5210-7Uq6YxiXyKZw.png', birthday = NULL, blood_type = NULL, voice_actor = '関俊彦', height = NULL, description = '沐絲はシャンプーの古くからの友人だが、彼女自身はそうは思っていないかもしれない。彼は人生の大半を彼女に恋い焦がれてきたが、彼女にとってはせいぜい「うっとうしい」存在に過ぎない。彼は眼鏡なしではよく見えずに、よく人を別の誰かと見間違えてしまう。 彼は、シャンプーが持つというこの「新しい婚約者」を探しに練馬へやって来て、愛する人の心を勝ち取ろうとそこに留まることにした。子供の頃、シャンプーは彼の求愛を拒絶したが、たとえ彼が大人になったとしても、アマゾンの掟によれば、その拒絶は今も有効なのである。' WHERE character_id = 'CH013956';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b2421-nwvYSxDyT8XJ.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佐久間レイ ', height = NULL, description = 'シャンプーは『ジョケツ族』出身の中国系アマゾンである。彼女は早乙女乱馬の3人の主要な婚約者のうちの1人だ。彼女は人操りが巧みである。彼女は、自分の気になる相手への立場を有利にするためなら、策略を弄したり、芝居を打ったり、あるいは完全に冷酷な振る舞いをすることさえ厭わないなど、狡猾で計算高い一面を繰り返し見せている。 しかし、シャンプーは自分が引き起こしたトラブルから楽しみを得ているようであり、特にその結果として乱馬に近づけるのであれば、なおさらである。' WHERE character_id = 'CH013957';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b349214-mhQKi0UpVFhu.jpg', birthday = NULL, blood_type = NULL, voice_actor = '関智一', height = NULL, description = '2024年のアニメシリーズに登場する男性キャラクター。風林館高校の放送部員であり、その独特な語り口や白熱した試合の生実況で知られている。（出典：『らんま1/2』ウィキ）' WHERE character_id = 'CH013958';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b10813-kUJbgTbOV77a.png', birthday = NULL, blood_type = NULL, voice_actor = '石田彰', height = NULL, description = '五釘は、乱馬と茜の同級生である。このシリーズの他の多くの男性キャラクターと同様、五釘も茜に恋をしているが、恥ずかしがり屋なため、その気持ちを伝えることができない。 また、彼は、リョーガやクノといった他の求愛者たちには到底敵わないことも自覚している。ゴスンクギはしばしば、ライバルたちにこっそり優位に立とうとするが、その試みは往々にして裏目に出る。クラスメートのほとんどは彼の存在に全く気づいておらず、ましてや、自分がアケネと結ばれるために彼らを排除しようとしていることなど、夢にも思っていない。' WHERE character_id = 'CH013959';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b181138-x6TUq6eHkRkN.png', birthday = NULL, blood_type = NULL, voice_actor = '橘龍丸', height = NULL, description = '国：韓国　シン・ヨンウは実生活での主人公の名前で、「グリード」はゲーム内の名前である。彼は人生において不運な負け犬だった。ゲーム『サティスファイ』をプレイするために必要なゲームカプセルを購入し、借金を背負ってしまった。 彼は過酷な生活を送り、莫大な借金を返済するために肉体労働を強いられたが、ゲームが得意ではなかったにもかかわらず、それでもプレイを続けた。彼のゲーム内キャラクター「グリード」は、ある時、伝説級のクラスチェンジアイテム（パグマのレア・ボック）を偶然手に入れるという幸運に恵まれ、' WHERE character_id = 'CH013960';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b182899-xtrJI0Uwm2e0.png', birthday = NULL, blood_type = NULL, voice_actor = '瀬戸麻沙美', height = NULL, description = '国：韓国  「血の魔女」として知られ、神ヤタンの第8の僕であるユ・ラは、高位かつ強力なユーザーである。  ユ・ラは、その美貌とヤタン教会への支援で最もよく知られるプレイヤーである。 その美しい容姿と卓越した能力から、テレビにも頻繁に出演する有名人である。「血の魔女」という不気味なニックネームとは裏腹に、彼女は多くの人々から愛され、尊敬される存在であると同時に、羨望の的でもあった。その抜群の美貌、完璧なゲームスキル、そして理想的なイ' WHERE character_id = 'CH013961';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b182895-ksw8vYpMDV3E.png', birthday = NULL, blood_type = NULL, voice_actor = '福積沙耶', height = NULL, description = 'ムムドの後継者であるユーフェミナは、かつて「デュプリケーター」であり、「永遠の王国」の伯爵でもあった。『サティスファイ』において、強力なユーザーであり、プライベートランカーでもある。彼女は、エピック評価を受けた初の隠しクラスユーザーである。 「デュプリケーター」として、彼女はランカーやネーム付きNPCから高ランクの呪文の複製を密かに収集している。詠唱なしでこれらの高ランクの呪文を唱えることができるため、人々は彼女を伝説級のクラスを持つ者、さらにはグリッドよりも強い存在だと誤解しがちだった。ユーフェミナは自身の能力を大いに誇りに思っている。しかし、彼女は……' WHERE character_id = 'CH013962';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/default.jpg', birthday = NULL, blood_type = NULL, voice_actor = '高山俊太朗', height = NULL, description = NULL WHERE character_id = 'CH013963';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b162723-2veq2yEY2trS.png', birthday = '9月15日', blood_type = NULL, voice_actor = '川島零士', height = NULL, description = '所属：夜桜家、浅野家　職業：学生、スパイ　タイヨウはこのシリーズの主人公である。彼はスパイであり、夜桜家のメンバーでもある。 タイヨウは、夜桜六美を守りたいという思いと、両親と弟の命を奪った自動車事故当日の真相を突き止めたいという思いから、夜桜家に嫁いだ。  太陽は、家族全員が交通事故で亡くなるという経験をする前は、陽気な性格だった。それは' WHERE character_id = 'CH013964';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b162724-MOaS8OsRvdyW.jpg', birthday = '6月6日', blood_type = NULL, voice_actor = '本渡楓', height = NULL, description = '所属：夜桜家　職業：学生、スパイ、夜桜家当主　ムツミは、このシリーズの主要な主人公の一人である。彼女は朝野太陽の妻であり、現在の夜桜家の当主である。  ムツミは、友人や家族のためになら何でもする覚悟がある、親切で思いやりのある少女だ。また、姉として、そして夜桜家の当主としても責任感があり、前当主であった亡き母の面影を受け継いでいる。朝野太陽と結婚して以来、彼女は' WHERE character_id = 'CH013965';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b169988-66qoT76fuJrA.png', birthday = '7月7日', blood_type = NULL, voice_actor = '内山夕実', height = NULL, description = '所属：夜桜家　職業：学生、スパイ    ナナオは主要な脇役の一人であり、夜桜家の次男である。  彼は甘えん坊で優しい（だがとてつもなく大きな）末っ子で、あらゆる種類の薬や治療薬を作るのが得意だ。バケツで顔を隠している。' WHERE character_id = 'CH013966';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b169990-7cPMIGNUYNoz.jpg', birthday = '2月2日', blood_type = NULL, voice_actor = '鬼頭明里', height = NULL, description = '年齢：21歳　所属：夜桜家　職業：スパイ   夜桜家の責任感の強い次女。小柄な体格とは裏腹に、並外れた体力と白兵戦の腕前を持つ。  双葉は一見、優しくないように見えるかもしれないが、実はとても親切で、誰に対しても手助けを惜しまない。 時には厳しい面も見せるが、心の中では家族のために最善を尽くそうとしている。長男の京一郎とは異なり、双葉はより冷静で、一歩引いた立場から家族を守っている。京一郎を簡単に落ち着かせることができるのは、ほとんどいつも彼女だ。' WHERE character_id = 'CH013967';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b165308-DtXZToMn5IjV.png', birthday = '1月1日', blood_type = NULL, voice_actor = '小西克幸', height = NULL, description = '所属：夜桜家　職業：スパイ、学校の副校長　京一郎は夜桜家の長男であり、同家でも最も強力なスパイである。 ある任務で、妹であり夜桜家の当主である夜桜六美が重傷を負ったことをきっかけに、京一郎はそれ以来、どんな犠牲を払っても彼女を守ることを誓った。京一郎は妹を溺愛する変人だ。 事実上ストーカー同然であり、妹の睦美を守るためなら何でもする。彼は彼女に対して過度に過保護であり、決して……' WHERE character_id = 'CH013968';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b169991-4YHk0PBwD6nG.png', birthday = '5月5日', blood_type = NULL, voice_actor = '松岡禎丞', height = NULL, description = '所属：夜桜家　職業：スパイ　この家の5番目の子で、陽気でいたずら好きな性格。極めてリアルな変装を仕立てることができる。' WHERE character_id = 'CH013969';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b170003-dj5rOnoUaYmT.png', birthday = '3月3日', blood_type = NULL, voice_actor = '興津和幸', height = NULL, description = '所属：夜桜家　職業：スパイ（ゴールドランク）　家族の中で常に神経質で、銃器を専門とする三男。よくゴミ箱に隠れている。　シンゾウは臆病者であり、本気を出せば強いにもかかわらず、自尊心はかなり低い。 シンゾーは子供の頃から、常に銃を1丁は身につけている。愛用する武器がないと、シンゾーは無力に見え、恐怖や苦痛にさらされると臆病者になってしまう。何か重要なことに集中しているかのように、普段はとは異なる、より真剣な雰囲気を醸し出している。' WHERE character_id = 'CH013970';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b169989-oaXnedVCznYd.jpg', birthday = '4月4日', blood_type = NULL, voice_actor = '悠木碧', height = NULL, description = '所属：夜桜家　職業：スパイ、ハッカー　 競争心が非常に強いゲーマーガールであり、一家の4番目の子供。極めて有能なハッカーである。' WHERE character_id = 'CH013971';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b169993-GsDcnkGk3NB9.png', birthday = '1月17日', blood_type = NULL, voice_actor = '松岡禎丞', height = NULL, description = '夜桜家の飼い犬。かなり気性の荒い子だ。' WHERE character_id = 'CH013972';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b22998-cg0IkjoiUMf7.png', birthday = '5月15日', blood_type = 'O', voice_actor = NULL, height = 175, description = '沢村栄純は長野県出身で、赤城中学校で野球をしていた。最後の試合の後、高島レイにスカウトされ、東京の清道高校の高校1年生として新たな道を歩むことになった。 彼は左投げのリリーフ投手であり、感情を込めて投球し、自分の本音を隠すことを決してためらわない。チームメイトの間では、短気で口うるさい性格として知られており、その態度はしばしばうっとうしいと受け取られるが、' WHERE character_id = 'CH013973';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b30267-RW6RhAA6iQdX.png', birthday = '11月17日', blood_type = 'B', voice_actor = NULL, height = 179, description = 'ポジション：捕手　打席：左　投球：右　美幸和也は清道高校の2年生で、野球部のエース捕手である。1年生の頃からすでに注目される捕手であり、その実力は全国的にも知られていた。美幸は、まだ中学1年生の時にレイにスカウトされていた。' WHERE character_id = 'CH013974';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b89310-inDo8ABMtDqf.png', birthday = '1月5日', blood_type = NULL, voice_actor = NULL, height = NULL, description = '彼は稲代工業高校の2年生で、同校野球部のエースである。関東地方随一の左腕投手と評されている。' WHERE character_id = 'CH013975';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b377807-6O2M2zZH4fOT.png', birthday = '12月6日', blood_type = 'A', voice_actor = '小鹿なお', height = NULL, description = '真面目で物静かな中学生の女の子だが、少しおっちょこちょいなところもある。以前は歌うことが大好きだったが、小学校の頃に病院に入院したことをきっかけに、内向的になってしまった。社交的な妹のフーを、少し羨ましく思っている。' WHERE character_id = 'CH013976';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b377806-kkYe1iOeRnNO.png', birthday = '6月16日', blood_type = 'O', voice_actor = '橘めい', height = NULL, description = '明るく無邪気な小学生の女の子。素直な性格で、楽しいことがあればすぐにワクワクして行動に移すため、いつもみんなの注目の的になっている。以前は姉のルイと仲が良かったが、最近は二人の間に距離が生まれているように感じ、少し寂しい思いをしている。' WHERE character_id = 'CH013977';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b402012-X2TG4ZhcqOiW.png', birthday = '11月4日', blood_type = 'AB', voice_actor = '根本京里', height = NULL, description = '彼女はアイドルファンで、特にリリーの大ファンだ。ルルト・リリーのコンサートを観た後、オーディションを受けてプロダクション・ワンス・モアに入団した。' WHERE character_id = 'CH013978';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324-PEf2pMfTqx96.png', birthday = '12月24日', blood_type = 'O', voice_actor = NULL, height = 151, description = 'プレースタイル：オールラウンダー    越前リョーマは『テニスの王子様』シリーズの主人公である。 彼は越前南次郎と竹内・越前凛子の息子である。リョーマは、かつてアメリカに在住していたが、日本へ帰国後すぐに青春学園（通称「セイガク」）に入学し、現在は1年生である。 中学1年生という若さにもかかわらず、リョーマは全米ジュニアテニス大会で連続優勝を果たし、すでにその名を轟かせていた――それもすべて' WHERE character_id = 'CH013979';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327-MtOFUTxZN6OY.png', birthday = '2月29日', blood_type = 'B', voice_actor = NULL, height = 167, description = 'プレースタイル：カウンターパンチャー　利き手：右　必殺技：ツバメ返し、ヒグマ落とし、白眼（トリプルカウンター）　不二周助は青春学園の3年生。コート上での戦術的才能から、「天才」の異名を持つ。 不二は明るく気さくで、周囲の人たちをふざけてからかうのが好きだ。  彼は不二家の次男である。名前の明かされていない父親は海外駐在員で、シリーズ中一度も登場しない。母親は49歳のヨシ' WHERE character_id = 'CH013980';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b126818-vWeIwxSERSHd.png', birthday = '11月26日', blood_type = NULL, voice_actor = '熊谷健太郎', height = 185, description = 'ライオスは自身のパーティのリーダーであり、ファリンの兄である。彼は北方大陸出身の長身の男だ。ライオスはモンスターに並々ならぬ情熱を注ぐ熱狂的なファンであり、強靭な戦士でもある。モンスターに対する深い知識と情熱が、戦闘やダンジョン探索において彼を際立たせている。 しかし、対人関係においてはしばしばつまずいてしまう。相手のニュアンスを察するのが苦手で、その結果、周囲への配慮や機転に欠けてしまう。このことが彼の人生を通じて多くのトラブルを引き起こしており、彼自身もその欠点を痛感し、不安を抱えている。' WHERE character_id = 'CH003704';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b127292-MAWgxbS0Cbrs.png', birthday = '4月19日', blood_type = NULL, voice_actor = '千本木彩花', height = 160, description = 'マルシルは、ライオスのパーティーに所属する魔法使いだ。彼女は北方大陸出身のエルフである。    マルシルは親切で、聡明、そして信念が強く、友人に対しては忠実である。しかし、非常に神経質で、自分の慣れた環境から大きく外れたこと（例えば、モンスターを食べることなど）には、なかなか対応できない面もある。 その生い立ちから、自身の魔法の能力には強い自信を持っており、パーティーの役に立てないときは孤独を感じることがある。彼女は魔法学院でトップクラスの生徒の一人であり、そこで――' WHERE character_id = 'CH003705';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b127689-SC65fBVrUx8v.png', birthday = '10月2日', blood_type = NULL, voice_actor = '中博史', height = 140, description = 'センシはライオスのパーティのメンバーである。東大陸出身のドワーフだ。10年間にわたりダンジョン内でモンスター料理を研究し、自給自足の生活を送ってきたセンシは、料理が大好きで、その知識や技術を喜んで人々に伝えている。 頼りになり、力強いが、かなり頑固で自分のやり方に固執する面もある。彼はダンジョンの自然環境や生態系の維持に貢献しており、自分自身もその一部だと考えている。魔法を嫌っており、それに対して非常に慎重な態度をとっている。' WHERE character_id = 'CH003706';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b130509-NFZ7xFt1kLqd.png', birthday = '5月18日', blood_type = NULL, voice_actor = '泊明日菜', height = 110, description = 'チルチャックはライオスのパーティの一員だ。彼は東大陸出身のハーフフォットである。チルチャックは抜け目なく、現実的で、口が鋭い。前払いがなければ仕事を引き受けない。 得意分野は錠前開けと、罠の見極め・解除だ。マルシルほどではないが、モンスターを食べることには比較的寛容な方だが、彼女と同様にヒューマノイドに関しては断固として拒否する。基本的にはパーティーの行動に同調するが、命に関わるような行動をとった際には率直に意見を述べる。彼の役割は……' WHERE character_id = 'CH003707';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239687-R4URaC2y1cfL.png', birthday = NULL, blood_type = NULL, voice_actor = '奈良徹', height = 145, description = 'ミックベルと共にカブルーのパーティーに加わったコボルド。この忠実なコボルドは、主への献身を決して揺るがすことはない。（出典：『ダンジョン飯 ワールドガイド：冒険者バイブル』）' WHERE character_id = 'CH003708';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323626-Er5ZuyR00ZBI.png', birthday = NULL, blood_type = NULL, voice_actor = '野上翔', height = 170, description = 'ドニは、現在フィオニルと共にダンジョンを探索している新人冒険者だ。彼は北大陸出身の背の高い男である。ドニの両親は農家だが、彼は世界を見てみたいと夢見ていたため、家を出て、探検の夢を追い求めてこの島へと旅立った。' WHERE character_id = 'CH003709';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324941-IJjO89n0MVZx.png', birthday = NULL, blood_type = NULL, voice_actor = '後藤光祐', height = 175, description = '種族：オーク　島にあるダンジョンに棲むオークたちの首領。' WHERE character_id = 'CH003710';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b149834-rZdkLULlqVoI.png', birthday = NULL, blood_type = NULL, voice_actor = '古谷佳乃', height = 195, description = 'Inutade is a member of Shuro''s party, serving him as one of his retainers. She is an ogre from the Eastern Archipelago.  Compared to her comrades in Shuro''s group, Tade is carefree, friendly, rather simple-minded, and gets hungry easily. Her real name is Hijouhi (ヒジョウヒ). She seems to have been close with Izutsumi.' WHERE character_id = 'CH003711';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b336445-qr3jmVMBYl7G.png', birthday = NULL, blood_type = NULL, voice_actor = '村瀬歩', height = 150, description = NULL WHERE character_id = 'CH003712';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239691-S5eRtO14dFw1.png', birthday = NULL, blood_type = NULL, voice_actor = '河村螢', height = 130, description = 'ナマリと同じく、ドワーフの女性だ。この強靭なドワーフの女性は、斧を振るってモンスターを次々と倒していく！（出典：『ダンジョン飯 ワールドガイド：冒険者バイブル』）' WHERE character_id = 'CH003713';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323629-pjZ7gU03RB0T.png', birthday = NULL, blood_type = NULL, voice_actor = '森田涼花', height = 150, description = 'フィオニルは、現在ドニと共にダンジョンを探索している新人冒険者だ。彼女は北中央大陸出身のハーフエルフである。  フィオニルはもともと、ダンジョンによって島で起きた変化を報告するために、西のエルフたちに雇われていた。しかし、ドニの話に深く心を動かされ、仕事を辞めて彼と共に冒険者になることを決意した。' WHERE character_id = 'CH003714';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b326447-TG79BYUIpDUK.png', birthday = NULL, blood_type = NULL, voice_actor = '大塚芳忠', height = NULL, description = 'ゴールデン・カントリーの元王であり、デルガルの父。' WHERE character_id = 'CH003715';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b331638-mEWawz7pzLKf.png', birthday = NULL, blood_type = NULL, voice_actor = '村瀬迪与', height = NULL, description = 'ゾン酋長の妹' WHERE character_id = 'CH003716';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239690-tD1W6tespVjH.png', birthday = NULL, blood_type = NULL, voice_actor = '富田美憂', height = 105, description = 'カブルーの一行に属するハーフフォット。どこへ行くにも、このケチなハーフフォットはいつもクロと一緒にいる！（出典：『ダンジョン飯 ワールドガイド：冒険者バイブル』）' WHERE character_id = 'CH003717';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b149833-nZ7ZMv8bHQon.png', birthday = '5月12日', blood_type = NULL, voice_actor = '内山昂輝', height = 155, description = 'ミスルンは、ダンジョンの調査に派遣されたエルフのグループ「カナリアス」の隊長である。彼は貴族の家系であるケレンシル家に生まれ、兄が一人いる。グループのリーダーを務める男性エルフで、淡い色の髪をショートボブにカットしている。 両耳の先端は切り取られている。目は片方しか機能していない。普段は、腕にストライプが入った長袖シャツ、ノースリーブのトップス、スカート、ズボン、そしてニーハイブーツを身につけている。他の多くのカナリアスのメンバーと同様、彼はハイ' WHERE character_id = 'CH003718';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239686-2hVxnDQgsyii.png', birthday = NULL, blood_type = NULL, voice_actor = '広瀬裕也', height = 140, description = 'カブルーのパーティーに所属する、古代の精霊魔法の研究者。この古代の精霊魔法の研究者は、4種類の精霊を操る。（出典：『ダンジョン飯 ワールドガイド：冒険者バイブル』）' WHERE character_id = 'CH003719';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239688-6SjaBoofH32x.png', birthday = NULL, blood_type = NULL, voice_actor = '長谷川育美', height = 180, description = 'キキは、タンスのパーティーに所属する双子のうちの一人です。彼女は背の高い人間です。  キキと双子の兄カカは遊牧民の一族に生まれたが、ある日、まだ幼い頃に酒場で置き去りにされ、馬小屋で眠っているところをタンズ夫妻に見つけられ、養子に迎えられた。二人はノームたちに囲まれて育った。' WHERE character_id = 'CH003720';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b248271-9FLbjsw97g0o.png', birthday = NULL, blood_type = NULL, voice_actor = '岸尾だいすけ', height = 170, description = 'リシオンは、ミスルンの率いるカナリア隊の一員だ。彼は気さくで、のんびりしたエルフである。他の多くのカナリアたちと同様、彼の耳には切り込みが入っており、これは黒魔術を使用した罪で有罪判決を受けた証である。' WHERE character_id = 'CH003721';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b130508-ZaP30snJccry.png', birthday = '12月1日', blood_type = NULL, voice_actor = '早見沙織', height = 170, description = 'ファリンはライオスの妹であり、支援魔法を専門とする魔術師である。彼女は北大陸出身の背の高い女性だ。ファリンは、他人を傷つけたくないと願う、とても優しく、思いやりがあり、気配りの行き届いた人物である。 彼女は、幼い頃から親しんできた安らぎを得られない死者の魂に対しても、この優しさを注いでいる。また、自己犠牲的で無鉄砲な一面もあり、愛する者の命が危険にさらされれば、躊躇なく彼らの代わりに攻撃を受け止めるだろう。兄と同様に、ファリンもまた狂信的な' WHERE character_id = 'CH003722';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135289-TaaQ8a4lHjEx.png', birthday = NULL, blood_type = NULL, voice_actor = '高橋李依', height = 165, description = '彼女は東方の国々出身の若い魔法使いで、カブルーのパーティの一員である。カブルーに対して強い嫉妬心を見せていることから、彼に恋愛感情を抱いている可能性が示唆されている。   彼女については、シュロの故郷以外の国出身である可能性が高いことや、魔法で雷を操れること以外、あまり知られていない。見知らぬ人に対してはかなり警戒心が強く、たいていの時、不機嫌そうな表情をしている。' WHERE character_id = 'CH003723';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239693-of1zdtMeYCj5.png', birthday = NULL, blood_type = NULL, voice_actor = '高橋良輔', height = 190, description = 'カカは、タンスのパーティーに所属する双子のうちの一人です。彼は背の高い男です。  カカと双子の妹キキは遊牧民の一族に生まれたが、ある日、まだ幼い頃に酒場で置き去りにされ、馬小屋で眠っているところをタンズ夫妻に見つけられ、養子として迎えられた。二人はノームたちに囲まれて育った。' WHERE character_id = 'CH003724';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b130507-iB88aMlQPuMz.png', birthday = '4月21日', blood_type = NULL, voice_actor = '神戸光歩', height = 150, description = 'イズツミは、かつてシュロのパーティーに所属していたが、現在はライオスのパーティーの一員である。彼女は東諸島出身の背の高い男（獣人）だ。  イヅツミは少々よそよそしいが、冷淡な人間というわけではない。かなり自己中心的なところがあるが、他者と協力することの大切さを学びつつある。彼女の原動力は、主に自分の呪いを解いてくれる人を見つけたいという強い決意にある。テーブルマナーはひどく、食の好みもうるさい。' WHERE character_id = 'CH003725';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b248270-j8asETxxmmAS.png', birthday = NULL, blood_type = NULL, voice_actor = '篠原侑', height = 140, description = '好きなもの：辛いもの 嫌いなもの：ニンジン  フレキは、肩までの長さのウェーブのかかった髪と乱れた前髪を持ち、他のカナリアたちと同様に両耳に切り込みが入っており、これは黒魔術を使ったという有罪の証を示している。 普段はベルト付きの短いチュニックにアンクルブーツを合わせ、他のメンバーと同じハイネックの服を着ており、鷹狩り用の手袋もはめている。フレキの魔法は、巻き尾の影のような黒い鳥や、3羽の小さなロ' WHERE character_id = 'CH003726';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135290-Xkr8Y1zxGniX.png', birthday = NULL, blood_type = NULL, voice_actor = '三木晶', height = 130, description = 'ナマリは、かつてライオスのパーティーに所属していたが、現在はタンスのパーティーの一員である。彼女は東大陸出身のドワーフだ。ナマリは武器や鍛冶について非常に詳しい。 仕事に関しては厳しい性格で、かつてのパーティーとはあまり良い関係ではないものの、それでも彼らのことを気にかけ、友人として接している。報酬のことで雇い主とよく口論になるという噂があり、また、彼女の父親は政府を騙したことで有名な武器商人であると言われている。' WHERE character_id = 'CH003727';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239694-Jftq6nrWipS9.png', birthday = NULL, blood_type = NULL, voice_actor = '所河ひとみ', height = 125, description = 'フローク夫人は、カカ・ブルードに鎮座する権力者たちから、ダンジョンの調査のために派遣されたノームの魔術師である。思慮深く、知恵に溢れた彼女は、総督の顧問を務めている。（出典：『ダンジョン飯 ワールドガイド：冒険者バイブル』）' WHERE character_id = 'CH003728';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b149835-awjvSuODLhQe.png', birthday = NULL, blood_type = NULL, voice_actor = '日笠陽子', height = 165, description = 'Maizuru is a member of Shuro''s party, serving him as one of his retainers. She is a tall-man from the Eastern Archipelago. Her real name is Iyo (イヨ).  Having known him his whole life, Maizuru is a brilliant yet overprotective teacher to Shuro. She is also a powerful mage who is able to perform a wide range of spells. Her magic seems to revolve around paper.' WHERE character_id = 'CH003729';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b149836-27TcUGqXcsVU.png', birthday = NULL, blood_type = NULL, voice_actor = '伊瀬茉莉也', height = 160, description = '好きなもの：トマト　嫌いなもの：レバー　ダンジョンの調査に派遣されたエルフのグループ「カナリーズ」の一員。貴族の家系であるヴァリ家の次女であり、両親の指名によりカナリーズに加わった。  彼女には長髪の妖精が使い魔として付き添っており、主に彼女と他のエルフたちとの間の連絡役を務めているようだ。彼女は使い魔を魔法の杖に変えて呪文を唱えることができ、その中には物理的な障壁を作り出す呪文も含まれている。彼女はかなりパニックになりやすいようだが、' WHERE character_id = 'CH003730';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b130506-S5gp6sZyi8q9.png', birthday = NULL, blood_type = NULL, voice_actor = '川田紳司', height = 180, description = 'シュロは、トーデン兄妹のパーティーに以前所属していた人物である。本名は半本俊朗。東方の出身で、長い黒髪をポニーテールに結い、色白の肌と黒い瞳をしている。ライオスよりは背が低いものの、マルシルよりは背が高い。 物語に再び登場する際、彼は以前よりやつれ、目はくぼみ、髭も剃っていない姿となっている。普段、シュロは控えめな性格で、他人に要求を突きつけることはめったにない。本音を他人に伝えるのが苦手で、その代わりに微妙な' WHERE character_id = 'CH003731';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135288-OxeQrxUVKLzJ.png', birthday = NULL, blood_type = NULL, voice_actor = '小林ゆう', height = 130, description = 'シスルは、「ザ・アイランド」のダンジョンを生み出した魔術師であり、黄金時代にデルガル王の宮廷に仕えた道化師でもある。その行動から、彼は漫画『i』『ダンジョン飯』</i>の主要な敵役となっている。  ダンジョンの支配者である「狂気の魔術師」は、ダンジョンの構造とそこに棲むモンスターの両方に対して絶大な力を持っている。また、ダンジョンの力によってその寿命も延ばされている。彼は王に対して並外れた忠誠心を持ち、王を何よりも守ろうとする。' WHERE character_id = 'CH003732';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b326444-FqBgNcZaXu9o.png', birthday = NULL, blood_type = NULL, voice_actor = '志村知幸', height = 175, description = 'かつてのゴールデン・カントリーの王であり、フライナーグの息子。' WHERE character_id = 'CH003733';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239685-Ivvqm6SjspUS.png', birthday = NULL, blood_type = NULL, voice_actor = '井上和彦', height = 130, description = 'フローク氏は、カハカ・ブルードに居を構える勢力から、ダンジョンの調査のために派遣されたノームの魔術師である。思慮深く、知恵に溢れた彼は、総督の顧問を務めている。（出典：『ダンジョン飯 ワールドガイド：冒険者バイブル』）' WHERE character_id = 'CH003734';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b329572-47gUV8k3FPWm.png', birthday = NULL, blood_type = NULL, voice_actor = '飛田展男', height = NULL, description = NULL WHERE character_id = 'CH003735';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239689-fgxv1NpdmrVT.png', birthday = NULL, blood_type = NULL, voice_actor = '鬼頭明里', height = 160, description = 'Benichidori is a member of Shuro''s party, serving him as one of his retainers, and is a member of the ninja squad who serves the Nakamoto clan. She is a tall-man from the Eastern Archipelago. Her real name is Matsu (マツ).  Benichidori is quiet, observant, cautious, and a skilled fighter. She has facial dysmorphia, meaning she is extremely insecure about the way her face looks, so she always wears heavy makeup.' WHERE character_id = 'CH003736';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b149837-rrRFcVCo0xCk.png', birthday = NULL, blood_type = NULL, voice_actor = '菊池こころ', height = NULL, description = 'オッタは、ミスルン船長の部隊の中で最も小柄なメンバーです。オッタの魔法は、土や石を操り、ダンジョン内に足場や壁を作り出すものです。' WHERE character_id = 'CH003737';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b135286-htqjXWhhjWSm.png', birthday = NULL, blood_type = NULL, voice_actor = '加藤渉', height = 170, description = 'カブルーはパーティーのリーダーであり、リンシャ、ミックベル、クロ、ダイア、ホルムと共にダンジョンを探索している。彼は西大陸のウタヤ出身の長身の男である。  カブルーは普段はのんびりとした印象を与えるが、実際には非常に社交的で、分析力と計算高さに優れ、強い正義感を持つ人物である。彼の趣味は、人々やその人間関係を観察・分析することであり、出会った人々の些細な詳細まですべて記憶している。必要とあれば、冷酷な一面も見せる。K' WHERE character_id = 'CH003738';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b324942-obbugk50R6jr.png', birthday = NULL, blood_type = NULL, voice_actor = '引坂理絵', height = NULL, description = NULL WHERE character_id = 'CH003739';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b239695-YjqtlftvzTjV.png', birthday = NULL, blood_type = NULL, voice_actor = '志田有彩', height = 170, description = 'Hien is a member of Shuro''s party, serving him as one of his retainers, and is a member of the ninja squad who serves the Nakamoto clan. She is a tall-man from the Eastern Archipelago. Her real name is Naka (ナカ).  Hien is a very capable and skilled fighter, though because of this, she can sometimes be overly blunt and self-confident. She considers herself to be very beautiful and doesn''t understand why Benichidori wears makeup.' WHERE character_id = 'CH003740';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b149838-i7FVH3q6gNvf.png', birthday = NULL, blood_type = NULL, voice_actor = '武田華', height = 165, description = 'ダンジョンの調査に派遣されたエルフのグループ「カナリアス」の一員。ミスルンの副官であるようだ。得意とする魔法は不明だが、ある場面で敵を「焼き尽くす」と宣言しており、スズランの花の枝のような形をしたトルを使用しているようだ。  彼女は古代魔法の使用、殺人教唆、文書偽造、詐欺の罪で有罪判決を受け、終身刑を言い渡された。シスヒスの最優先事項は、ミスルンを生き延びさせることにあるようだ。なぜなら、ミスルン自身はそれを忘れてしまう傾向があるからだ。' WHERE character_id = 'CH003741';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123212-ewZgUQr9vvEM.png', birthday = '10月20日', blood_type = NULL, voice_actor = '千葉翔也', height = 176, description = '綾小路は、目立たず、控えめな学生である。彼は極めて聡明であり、周囲の人々の感情を洞察する深い洞察力を持っていることが示されている。 入試以前の彼の人生については、ほとんど何も知られていない。彼は極めて計算高く、超人的な知性、洞察力、そして強さを備えている。戦闘に長けており、周囲の人々を容易に操ることができる。彼は友人たちを非常に大切にしており、できる限り彼らを守ろうとしている。' WHERE character_id = 'CH003742';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b124691-S9GyfwMAkkJ9.jpg', birthday = '3月12日', blood_type = NULL, voice_actor = '日高里菜', height = 150, description = '坂柳有栖は、葛城康平と共に1年A組の学級委員の一人である。彼女は先天性心疾患を患っており、そのせいで身体能力に制限がある。   彼女は「流れに身を任せる」ような態度の持ち主のようで、ほとんどの状況を文句一つ言わずに受け入れているが、葛城がクラスの成績について言及した際には、退屈な状況が嫌だと口にした。保守的な姿勢をとる葛城康平とは異なり、有栖は革新的な考え方を持ち合わせている。二人は力を合わせて、クラスを効果的に率いている。' WHERE character_id = 'CH003743';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123213-jUfrGBXfW7BL.png', birthday = '2月15日', blood_type = NULL, voice_actor = '鬼頭明里', height = 156, description = '綾小路の隣に座っている美しい少女。友情に関しては綾小路とは正反対で、友情を軽視し、友達を作る必要性を感じていないため、クラスメートとはあまり交流を持たない。自分がD組に配属されたことに納得しておらず、A組への昇格を目指している。' WHERE character_id = 'CH003744';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123216-N9tQZf2XIKu6.png', birthday = '7月20日', blood_type = NULL, voice_actor = '東山奈央', height = 159, description = 'ホナミを一言で表すなら、彼女は心から親切で、慈愛に満ち、根っからの平和主義者であり、卑怯な手段や暴力に反対していると言えるでしょう。 彼女の主な特徴の一つは、利他的で人を支える性格であり、優れた対人スキルと、生まれつき人を大切にする姿勢が相まって形成されています。また、ホナミはカリスマ性がありエネルギッシュな人物でもあり、他の多くの上流階級の学生とは異なり、下層階級の人々に対してもその優しく温厚な人柄を惜しみなく示しています。' WHERE character_id = 'CH003745';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b158988-P28e8SU3WpGK.png', birthday = '4月3日', blood_type = NULL, voice_actor = '岩澤俊樹', height = NULL, description = '高円寺六助は1-D組の生徒の一人だ。彼は名門の学者一家の出身である。しかし、その自己中心的な振る舞いのせいで、D組に配属されてしまった。' WHERE character_id = 'CH003746';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191504-gMTtAwzDo8Sp.png', birthday = '5月6日', blood_type = NULL, voice_actor = '小原好美', height = NULL, description = '橘茜は、アドバンスト・ナーチャリング高校の3年A組を卒業した元生徒であり、元生徒会書記を務めていた。' WHERE character_id = 'CH003747';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191401-QIpXOM9iZoG2.jpg', birthday = '4月25日', blood_type = NULL, voice_actor = '田澤茉純', height = NULL, description = '松下は2年D組の生徒の一人だ。彼女は物静かで、お姉さんっぽい性格をしている。基本的には男子も女子も区別なく親切に接するが、自ら進んで友達を作ろうとはしない。' WHERE character_id = 'CH003748';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b294554-woCpCOxQBJwu.jpg', birthday = '6月11日', blood_type = NULL, voice_actor = '島田愛野', height = NULL, description = '清孝の第一印象によると、タケコはためらうことなく本音を口にするタイプだ。彼女は、同級生の伊吹澪と同じように、少し一匹狼なところがある。' WHERE character_id = 'CH003749';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b189728-hkfJGlmYbBmx.png', birthday = '1月6日', blood_type = NULL, voice_actor = '雨宮天', height = NULL, description = '朝比奈なずなは、アドバンス・ナーチャリング高校の3年A組の生徒である。    なずなは少し荒っぽいところもあるが、気さくで遊び心のある2年生たちからは非常に好かれており、大きな影響力を持っている。一方で、責任感が強く、他人から受けた恩は決して忘れない。 彼女は人を早合点して判断してしまう癖があり、綾小路清隆の場合も、彼が自分の最も大切な持ち物を取り戻してくれた「神のような人物」であるにもかかわらず、最初は「哀れな女たらし」だと決めつけてしまった。彼女はそれを恥じ、困惑している。' WHERE character_id = 'CH003750';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191508-GekReas1uAlI.png', birthday = '2月1日', blood_type = NULL, voice_actor = '金元寿子', height = NULL, description = '星之宮知恵は1年B組の担任教師である。明るく、茶目っ気のある性格で、綾小路からは「高校時代から全く成長していない」と評されている。 Aクラス昇格に関わる事柄については、彼女の真面目な一面が垣間見える。同僚の茶柱佐枝とは、進学育成高校時代の同級生だった。' WHERE character_id = 'CH003751';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123218-HLOaxZINQojE.png', birthday = '9月1日', blood_type = NULL, voice_actor = '逢坂良太', height = 174, description = 'D組のリーダー的存在。学業とスポーツの両方で優れた能力を持ち、クラスメートからは非常にハンサムだと評されている。また、非常に思いやりのある人物であり、他人を自分より優先し、誰に対しても平等に接する。完璧な男子生徒と見なされており、彼がD組に配属された理由は当初、謎とされていた。' WHERE character_id = 'CH003752';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b163517-pBRJeR0pkw0Z.png', birthday = '11月5日', blood_type = NULL, voice_actor = '巽悠衣子', height = NULL, description = 'ハルカはごく普通の女の子だが、他者に対してあまり心を開いていない。クラスの水泳の授業に参加しなかったことからもそれがうかがえる。彼女はトラブルを避けるため、一人でいることを好み、人に迷惑をかけないようにしている傾向がある。 彼女は「神レベルの美貌」を持っていると見なされており、男子から色目で見られることが多いため、人目を避けて過ごそうとする。普段は学校の制服を着ているが、シャツの上のボタンを一つ外し、ネクタイも比較的緩めているのが特徴だ。' WHERE character_id = 'CH003753';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b284290-pAwIYIgcP5OH.jpg', birthday = NULL, blood_type = NULL, voice_actor = '本泉莉奈', height = NULL, description = '森寧々は、堀北のクラスの生徒の一人です。' WHERE character_id = 'CH003754';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174781-jzyPHUz3JBwi.png', birthday = '7月27日', blood_type = NULL, voice_actor = '小松未可子', height = NULL, description = '伊吹澪は1年C組の生徒である。学業成績が優秀なだけでなく、その身体能力も侮れない。彼女は戦闘に長けており、多くの武術家にも引けを取らない数々の武術の技を身につけている。' WHERE character_id = 'CH003755';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191506-4eKgEo4z62Cz.png', birthday = '6月21日', blood_type = NULL, voice_actor = '香田沙織', height = NULL, description = '篠原さつきは2年D組の生徒の一人だ。容姿は平均以下と見なされている。物言いがはっきりした性格で、イケと口論している姿をよく見かける。' WHERE character_id = 'CH003756';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b288362-ftZjFHEiFelR.jpg', birthday = NULL, blood_type = NULL, voice_actor = '竹内良太', height = NULL, description = '坂柳会長が一時的に職務を停止された後、彼は同校の代理校長に就任した。' WHERE character_id = 'CH003757';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207027-abI5hAZvWaxI.png', birthday = '4月24日', blood_type = NULL, voice_actor = '阿座上洋平', height = NULL, description = '正義は極めて利己的な人物であり、自分以外の誰に対しても真の忠誠心など持っていない。常にトップの座に留まるため、彼は常に勝者側に立ち、勝つ側に賭ける。 1年生の初めにA組のリーダー争いが勃発した際、正吉は坂柳有栖こそがリーダーにふさわしいと見極め、すぐに彼女の派閥に加わり、その側近の一員となった。' WHERE character_id = 'CH003758';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b282232-MlTb9J4Ba0Hn.jpg', birthday = '11月11日', blood_type = NULL, voice_actor = '石川界人', height = NULL, description = '柴田 颯は、一ノ瀬先生のクラスの生徒の一人です。' WHERE character_id = 'CH003759';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b273646-JGrI4rwCGhBy.jpg', birthday = '6月16日', blood_type = NULL, voice_actor = '阿部大樹', height = NULL, description = '池寛治は、1-D組の生徒の一人で、「Dクラスの3人のバカ」の一人として知られている。頭は悪いが、コミュニケーション能力は抜群だ。' WHERE character_id = 'CH003760';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b173450-3W4X5drCuO21.png', birthday = '7月11日', blood_type = NULL, voice_actor = '郷田翼', height = NULL, description = '幸村輝彦は1年D組の生徒である。学力は優秀だが、運動能力が低く、対人スキルも不足していたため、このクラスに配属された。   綾小路グループ結成の際、彼は、家族を去った母親から付けられた「輝彦」という名前が気に入っていないことが明らかになる。彼は、父親から付けられた「啓成」という名前を好んでいる。' WHERE character_id = 'CH003761';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207026-M98kkCZdkIfP.png', birthday = '8月29日', blood_type = NULL, voice_actor = '日野聡', height = 180, description = '康平は、1-A組に入るために懸命に努力し、坂柳有栖と共にクラスの代表の一人となった聡明な生徒である。礼儀作法や品行を重んじる真面目な性格だ。 彼はクラスの主導権を巡って坂柳と対立しており、自身の派閥を率いて彼女に反対している。病気のため頭は禿げている。双子の妹がおり、二人はもともと孤児だった。   第2巻 2年' WHERE character_id = 'CH003762';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b281121-HoL7mtYJdfBd.png', birthday = '4月17日', blood_type = NULL, voice_actor = '野津山幸宏', height = NULL, description = '鬼頭隼は、坂柳のクラスの生徒の一人である。' WHERE character_id = 'CH003763';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b141122-6Zk52eU3VK3O.png', birthday = '3月8日', blood_type = NULL, voice_actor = '竹達彩奈', height = 154, description = '彼女は態度の悪い少女で、D組のヒエラルキーの頂点に立っている。クラス内の上位2位を巡って、クシダと争っている。 不注意で傲慢、だらしがないという印象を与えるが、ケイの本当の姿は極めて論理的で鋭い頭脳の持ち主だ。周囲の状況や人々を読み取る能力に長けており、しばしば正しい判断を下す。' WHERE character_id = 'CH003764';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123214-Ym9cldopi3yR.png', birthday = '1月23日', blood_type = NULL, voice_actor = '久保ユリカ', height = 155, description = '彼女はD組のアイドルとして、男女問わず絶大な人気を誇っている。彼女はD組だけでなく、誰とでも友達になりたいと考えている。クラスメイトのホリキタとも仲良くしたいと思っている。' WHERE character_id = 'CH003765';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b273648-bb7WViiKWiDb.jpg', birthday = '5月12日', blood_type = NULL, voice_actor = '本橋大輔', height = NULL, description = '戸塚弥彦は1年A組の生徒で、葛城派に所属している。' WHERE character_id = 'CH003766';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b294559-xCpF0d7AnUMt.jpg', birthday = NULL, blood_type = NULL, voice_actor = '山下誠一郎', height = NULL, description = '生人は、前生徒会長の堀北学を深く尊敬し、崇拝しており、学校が定めた規則は守られなければならないと信じている。彼は南雲に対して憎しみと軽蔑を抱いており、その明確な理由はまだ不明だが、どうやら南雲とは不愉快な過去があるようだ。' WHERE character_id = 'CH003767';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b284289-HXcgPYmSzIXr.png', birthday = '11月28日', blood_type = NULL, voice_actor = '白城なお', height = NULL, description = '白波千尋は、一ノ瀬のクラスの生徒の一人です。' WHERE character_id = 'CH003768';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191507-YIt6i1p7GIXU.png', birthday = '2月20日', blood_type = NULL, voice_actor = '佐倉綾音', height = NULL, description = '神室真澄は2年A組の生徒で、美術部の部員である。彼女は坂柳派の核心メンバーの一人だが、坂柳が彼女の犯罪歴に関する情報を握っているため、その立場に留まっているに過ぎないことが示唆されている。' WHERE character_id = 'CH003769';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b284288-Nu0hmRlKkFFi.jpg', birthday = '1月1日', blood_type = NULL, voice_actor = '川辺俊介', height = NULL, description = '外村秀雄は、堀北のクラスの生徒の一人である。' WHERE character_id = 'CH003770';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b159627-kWwSUA1XR1Kx.png', birthday = '10月20日', blood_type = NULL, voice_actor = '水中雅章', height = 173, description = '龍園翔は1年C組の学級委員長であり、悪名高い不良として知られている。彼は信頼ではなく、恐怖によってクラスを統率している。彼には汚い仕事を請け負う手下たちがおり、それが彼の恐ろしい評判の一因となっている。' WHERE character_id = 'CH003771';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b197977-Oc49nfQWbBBN.png', birthday = NULL, blood_type = NULL, voice_actor = '斉藤壮馬', height = 178, description = '南雲雅は、アドバンスト・ナーチャリング高校の3年A組の生徒です。' WHERE character_id = 'CH003772';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285107-n9FrjdCynyeB.jpg', birthday = NULL, blood_type = NULL, voice_actor = '田中美海', height = NULL, description = NULL WHERE character_id = 'CH003773';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b136233-wmiulsKzTMND.png', birthday = '8月21日', blood_type = NULL, voice_actor = '桜木アミサ', height = NULL, description = 'メイ・ユーは中国系の出身で、学業優秀な生徒の一人として描かれている。彼女は平田陽介に明らかに好意を抱いている。' WHERE character_id = 'CH003774';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207028-UARWe5XOhSj1.png', birthday = '2月16日', blood_type = NULL, voice_actor = '杉崎亮', height = NULL, description = '真島は英語教師であり、1年A組の担任である。真島は仕事に真摯に取り組み、生徒を何よりも大切にする人物である。' WHERE character_id = 'CH003775';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b273647-DByKPQyQaeOw.jpg', birthday = '1月16日', blood_type = NULL, voice_actor = '小山力也', height = NULL, description = '山田アルベルトは1年C組の生徒の一人です。' WHERE character_id = 'CH003776';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b290862-wFNlgaXUL8gi.jpg', birthday = NULL, blood_type = NULL, voice_actor = '増谷康紀', height = NULL, description = NULL WHERE character_id = 'CH003777';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207023-dyxChkVbd5qZ.jpg', birthday = '5月30日', blood_type = NULL, voice_actor = '岩中睦樹', height = NULL, description = 'ハルキは1-D組の生徒だ。彼はイケや須藤とともに、D組の「三バカ」の一人である。嘘をつく癖があり、成績はクラスで最下位だ。 友人たちと同様、春樹にも変態的な一面があり、女子を覗き見しようとしたことから、櫛田キキョウに惹かれている。また、佐倉愛里や長谷部波瑠加にも強く惹かれており、その理由は主に彼女たちの豊満な体型と物静かな性格にある。' WHERE character_id = 'CH003778';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285904-JBTG7yHJkDxC.jpg', birthday = NULL, blood_type = NULL, voice_actor = '中野さいま', height = NULL, description = '木下美野里は、龍園のクラスの生徒の一人です。' WHERE character_id = 'CH003779';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207024-RmtB15Cndzk3.png', birthday = '7月13日', blood_type = NULL, voice_actor = '鈴木崚汰', height = NULL, description = '中学時代、アキトはアーチェリーに夢中になり、同校のアーチェリー部に入部して、県大会にも出場した。しかし、その過程で、学業など他の活動や義務をおろそかにするようになってしまった。 その頃、彼は他人と喧嘩を仕掛けるなどして、周囲に騒動を引き起こし始めた。そのこと、そして学業を疎かにしていたことが重なり、彼はDクラスの生徒と評価されることになった。高校でも、彼は再びアーチェリー部の部員となった。彼は清隆の親友であり、' WHERE character_id = 'CH003780';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123217-sZaSZQGBYTcu.png', birthday = '5月20日', blood_type = NULL, voice_actor = '佐藤利奈', height = 160, description = '主人公のクラス（D組）の担任教師。もともとクラスに対して無関心で、クラス対抗戦では生徒たちを助けるための行動をほとんど取らず、概してやる気のないまま過ごしている。' WHERE character_id = 'CH003781';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b290860-WCJyDzVWR3Iy.jpg', birthday = NULL, blood_type = NULL, voice_actor = '宮本充', height = NULL, description = '坂柳成臣は、本作の物語が始まる7～8年前に、父親の後を継いで会長の座に就いた。会長に就任する前から綾小路先生と面識があり、先生に対して深い敬意を抱いているようだ。また、娘の坂柳有栖と共に「ホワイト・ロム」を訪れたこともある。' WHERE character_id = 'CH003782';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123219-OEMawnnYXMFY.png', birthday = '4月24日', blood_type = NULL, voice_actor = '梅原裕一郎', height = 178, description = '彼は生徒会の会長であり、堀北鈴音の実の兄である。' WHERE character_id = 'CH003783';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207025-gpnIy6ewtfVu.png', birthday = '10月5日', blood_type = NULL, voice_actor = '竹内栄治', height = 183, description = 'ケンは1-D組に所属し、バスケットボール部にも入っている。学力が低いため、「D組の3大バカ」の一人と呼ばれている。 それにもかかわらず、彼の運動能力は間違いなく学校でもトップクラスだ。スズネに助けられたことをきっかけに、彼女に好意を抱くようになる。スズネの絶え間ない指導のもと、彼は徐々に成長し、学業も向上してクラスの最下位から抜け出し、彼女の信頼を勝ち取っていく。' WHERE character_id = 'CH003784';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b123215-sMQJk35TqQv4.jpg', birthday = '10月15日', blood_type = NULL, voice_actor = '市道真央', height = 153, description = '写真に夢中な女の子。外で立っているのが大嫌いで、モデルのような写真を撮るのが好きだ。' WHERE character_id = 'CH003785';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285111-kNry6AiQTlFo.jpg', birthday = NULL, blood_type = NULL, voice_actor = '鈴代紗弓', height = NULL, description = NULL WHERE character_id = 'CH003786';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323944-0MjOpgAZDbnb.png', birthday = NULL, blood_type = NULL, voice_actor = '市川蒼', height = NULL, description = '一ノ瀬のクラスの生徒。' WHERE character_id = 'CH003787';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b163519-as1ccGaDehxI.jpg', birthday = '2月28日', blood_type = NULL, voice_actor = 'Lynn', height = NULL, description = '彼女は1-D組の生徒です。' WHERE character_id = 'CH003788';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b282226-El2d8fl0XMDB.jpg', birthday = '7月1日', blood_type = NULL, voice_actor = '小市眞琴', height = NULL, description = '小野寺かや乃は、堀北のクラスの生徒の一人だ。彼女は水泳部の部員であり、クラス内の女子の中で最も泳ぎが上手い。' WHERE character_id = 'CH003789';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b163518-xnSqZflOp9Wm.png', birthday = '1月21日', blood_type = NULL, voice_actor = '高橋李依', height = NULL, description = '椎名ひよりさんは、1年C組の生徒の一人で、一匹狼タイプだ。彼女は物静かな女の子だが、時折微笑む姿も見られる。文学への興味を共有できる人に出会えるかもしれないと思い、いつもカバンに本を入れて持ち歩いている。 1-C組には文学に興味を持つ生徒が誰もいないため、彼女には話し相手がいません。彼女はいつも丁寧な口調で話します。クラス同士が競い合うような状況が嫌いで、みんなが仲良くしてほしいと願っています。' WHERE character_id = 'CH003790';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b282231-gJ2olbv3ErMv.jpg', birthday = '8月24日', blood_type = NULL, voice_actor = '下地紫野', height = NULL, description = '井の頭心は、堀北のクラスの生徒の一人だ。' WHERE character_id = 'CH003791';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b285108-HYji69uXcgh0.jpg', birthday = NULL, blood_type = NULL, voice_actor = '富田美憂', height = NULL, description = NULL WHERE character_id = 'CH003792';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b282230-AhTZ1ajQYoV2.jpg', birthday = '4月14日', blood_type = NULL, voice_actor = '帆世雄一', height = NULL, description = NULL WHERE character_id = 'CH003793';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323945-cCI4iN1eLiGW.png', birthday = NULL, blood_type = NULL, voice_actor = '金子誠', height = NULL, description = '一ノ瀬のクラスの男の子。' WHERE character_id = 'CH003794';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b207022-dfXyWDXyBVKC.png', birthday = '12月5日', blood_type = NULL, voice_actor = '若山晃久', height = 174, description = '1-B組の一員であり、一之瀬帆波の右腕。 竜司についてはあまり知られていないが、真面目な態度で勉学に励む生徒のようで、須藤健の事件で一之瀬帆波を助けたことからもわかるように、非常に頼りになる人物である。D組を見下すことなく、彼らと仲良くしていることから、人当たりが良いことがうかがえる。' WHERE character_id = 'CH003795';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b191505-HKDg5oKO1ErQ.jpg', birthday = NULL, blood_type = NULL, voice_actor = '佳穂成美', height = NULL, description = '小橋夢は1年B組の生徒の一人です。' WHERE character_id = 'CH003796';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b158734-k8FAVIyXKdW1.jpg', birthday = '11月11日', blood_type = 'O', voice_actor = '小林千晃', height = 171, description = 'このシリーズの主人公。マッシュはイーストン魔法学園の1年生で、アドラー寮の寮生である。魔法の才能は全くないという特異な体質を持つ一方で、超人的な力を持っており、それが学園内で彼を一際際立たせている。  マッシュは普段は物静かで優しい性格だ。しかし、家族や友人が傷つけられているのを見かけると、凄まじい怒りを露わにする。また、極めて純真で従順なため、その性格を悪用されることも多いが、その強さのおかげで、ほぼあらゆる状況を好転させることができる。' WHERE character_id = 'CH003797';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174369-VjKvYJbXLO5I.jpg', birthday = '4月1日', blood_type = NULL, voice_actor = '江口拓也', height = NULL, description = '所属：イーストン・マジック・アカデミー　職業：学生　ドット・バレットは、イーストン・マジック・アカデミーの1年生であり、『マシュレ』シリーズの主人公の一人である。  ドットは短気で生意気な性格だが、心の底では優しい男であり、自分が間違っていた場合は素直に謝る。また、恋に落ちやすい一面も描かれている。' WHERE character_id = 'CH003798';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b167819-2pddKcJiApjD.jpg', birthday = NULL, blood_type = NULL, voice_actor = '上田麗奈', height = 162, description = '所属：イーストン魔法学院　職業：学生　レモン・アーバインは、イーストン魔法学院の1年生です。短いブロンドの髪にオレンジ色のリボンを結んでいます。右目の下には、半月形のカーブを描いた直線のマークがあります。普段はイーストン魔法学院の制服を着ています。  レモンは少しお調子者だが、心根は誠実で、他人を裏切るようなことは到底できないようだ。また、とても臆病で、人との会話では話を大げさに言いがちだ。' WHERE character_id = 'CH003799';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b172075-aOsZuM7D0bcW.jpg', birthday = '2月3日', blood_type = NULL, voice_actor = '石川界人', height = 178, description = '所属：イーストン・マジック・アカデミー　職業：学生　ランス・クラウンは、入学試験で1位を獲得し、2つのマークを持っていることで知られる、イーストン・マジック・アカデミーの学生である。  幼い頃のランスは、たとえ喧嘩に巻き込まれることになっても、他人から不当な扱いを受けている人々を庇おうとする、非常に思いやりのある人物だった。ランスは妹を何よりも大切にしており、妹が連れ去られるのを防ぐために「神の予言者」になることを誓っている。' WHERE character_id = 'CH003800';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b174368-tYxOTsrCDEk9.jpg', birthday = '1月23日', blood_type = 'A', voice_actor = '川島零士', height = 170, description = 'フィン・エイムズは、イーストン・マジック・アカデミーの1年生で、アドラー寮の寮生である。彼はレイン・エイムズの弟である。フィンはマッシュのルームメイトであり、マッシュにとって最初の、そして最も親しい友人である。' WHERE character_id = 'CH003801';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b216157-BV5gcRKCoJ3k.jpg', birthday = '8月3日', blood_type = 'A', voice_actor = '島﨑信長', height = 175, description = 'カルド・ゲヘナは、神聖な予言者であり、魔法局の傘下組織である「魔法才能管理局」の長を務めている。' WHERE character_id = 'CH003802';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b262142-NBHIZfNw94oM.jpg', birthday = '5月11日', blood_type = 'AB', voice_actor = '古賀葵', height = 160, description = 'ラブ・キュートは、イーストン・マジック・アカデミーの2年生です。彼女は「マギア・ルプス」の第五の牙です。' WHERE character_id = 'CH003803';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b262136-vmc8MJHetX8h.png', birthday = '11月11日', blood_type = NULL, voice_actor = '三木眞一郎', height = NULL, description = '「イノセント・ゼロ」は、同名の犯罪組織のリーダーであり、本作の主要な敵役である。かつては、ウォールバーグと共にアダム・ジョブズの弟子だった。' WHERE character_id = 'CH003804';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b301344-VtiVh42Go1LX.png', birthday = NULL, blood_type = NULL, voice_actor = '諏訪部順一', height = NULL, description = '神聖なる先見者であり、魔法保安部隊の隊長。この国のほとんどの住民とは異なり、リョウは、自分を感心させさえすれば、魔法を使えない人々に対しても何の偏見も抱かない。また、彼は非常に自尊心が強く、自らをスターだと見なしており、自分の行動をナレーションで語ってしまうほどである。' WHERE character_id = 'CH003805';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b262146-OFBg195UmJuj.png', birthday = '11月1日', blood_type = 'O', voice_actor = '谷山紀章', height = 180, description = 'レナトス・リボルは、神の予言者であり、魔法局の傘下組織である「魔法墓地管理局」のメンバーである。' WHERE character_id = 'CH003806';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b262134-tF0VrJEteYcW.png', birthday = '7月5日', blood_type = NULL, voice_actor = '七海ひろき', height = NULL, description = '「マギア・ルプス」の第二の牙。' WHERE character_id = 'CH003807';
