UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323781-j7K6oPPUJyes.png', birthday = '12月13日', blood_type = 'A', voice_actor = '日向朔公', height = NULL, description = 'イーストン・マジック・アカデミーの2年生。彼と双子の兄トロンは、マーガレットの秘書を務めている。チェロは、自身のチェロを使ってマーガレットの魔法をサポートしている。' WHERE character_id = 'CH003822';
