UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323162-Zwm0KrxsELwt.png', birthday = NULL, blood_type = NULL, voice_actor = '荒井洸貴', height = NULL, description = '彼はオシの友人の一人だ。' WHERE character_id = 'CH003834';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206490-zXi4Z96IDuW3.png', birthday = '7月20日', blood_type = 'O', voice_actor = '本渡楓', height = NULL, description = 'リンは、ユキの大学時代の友人だ。彼女は、ユキとイツオミの関係を心から応援している。また、イツオミのいとこであるキョウヤのことが好きだ。' WHERE character_id = 'CH003835';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323964-U32mFNVSu18z.png', birthday = NULL, blood_type = NULL, voice_actor = '髙橋ミナミ', height = NULL, description = NULL WHERE character_id = 'CH003836';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206489-6Ewj3mocooVc.png', birthday = '4月5日', blood_type = 'A', voice_actor = '大塚剛央', height = NULL, description = 'ユキの幼なじみで、彼女のために手話を学び、その腕前も非常に優れている。幼い頃からユキを知っており、彼女に想いを寄せているため、ユキとイツオミの関係について心配している。' WHERE character_id = 'CH003837';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323965-9MbWSn6DGHb9.png', birthday = NULL, blood_type = NULL, voice_actor = '菱川花菜', height = NULL, description = NULL WHERE character_id = 'CH003838';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b206491-VP37C9wssba3.png', birthday = '10月16日', blood_type = 'B', voice_actor = '逢坂良太', height = NULL, description = 'イツオミの従兄弟。彼は小さなバーでバリスタをしている。' WHERE character_id = 'CH003839';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b246023-JY3YgmQALjHM.png', birthday = '2月1日', blood_type = NULL, voice_actor = '畠中祐', height = NULL, description = 'シンはイツオミの高校時代の同級生で、現在は美容師として働いている。普段はクールな性格だが、お酒を飲むと急に陽気な性格に変わる。よくエマとつるんでおり、彼女の恋愛相談役を務めている。' WHERE character_id = 'CH003840';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b282662-eMBZCTHgAIto.png', birthday = '12月27日', blood_type = NULL, voice_actor = '東山奈央', height = NULL, description = NULL WHERE character_id = 'CH003841';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b323164-LVn9PrytpUME.png', birthday = NULL, blood_type = NULL, voice_actor = '増田ゆき', height = NULL, description = 'ユキの母親。' WHERE character_id = 'CH003842';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b327618-MGSkns4tcf9x.png', birthday = NULL, blood_type = NULL, voice_actor = '天野宏郷', height = NULL, description = NULL WHERE character_id = 'CH003843';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b305774-XRZfB8KQ22te.png', birthday = '8月11日', blood_type = NULL, voice_actor = '坂田将吾', height = NULL, description = 'ただ「何か特別なこと」を夢見る、ごく普通の高校生。鈴音や一樹と一緒に学校から帰宅途中、リングル王国への召喚に巻き込まれてしまった。 彼が治癒魔法の才能を持っていることが判明すると、ローズの救命チームに強制的に加入させられる。そこで、地獄のような訓練を経て、強靭な肉体を手に入れることになる。' WHERE character_id = 'CH003844';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b313120-LYRDZTKy1hep.png', birthday = NULL, blood_type = NULL, voice_actor = '田中敦子', height = NULL, description = 'リングル王国救命チームのリーダー。彼女は治癒魔法使いだが、戦闘能力も非常に高く、かつては騎士団の大隊長を務めていた。彼女は、同じく治癒魔法使いであるウサトを救命チームに強制的に加入させ、右腕として育成している。' WHERE character_id = 'CH003845';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325574-K9q1yDjIrHvd.png', birthday = NULL, blood_type = NULL, voice_actor = '中村源太', height = NULL, description = NULL WHERE character_id = 'CH003846';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325582-bybgtCV7aNDH.png', birthday = NULL, blood_type = NULL, voice_actor = 'てらそままさき', height = NULL, description = NULL WHERE character_id = 'CH003847';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b332073-LvKtbUOGbzAv.png', birthday = NULL, blood_type = NULL, voice_actor = '小原好美', height = NULL, description = 'ローズの副司令官を務めた騎士。' WHERE character_id = 'CH003848';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b311042-Hf5D2weImE8V.png', birthday = NULL, blood_type = NULL, voice_actor = '会沢紗弥', height = NULL, description = 'アマコは、リングル王国の城下町に住み、果物店で手伝いをしている獣人少女だ。彼女はウサトに気があるようだ……' WHERE character_id = 'CH003849';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325575-Tup25X7UMQCB.png', birthday = NULL, blood_type = NULL, voice_actor = '上田麗奈', height = NULL, description = NULL WHERE character_id = 'CH003850';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325583-74cMpixZ1DHE.png', birthday = NULL, blood_type = NULL, voice_actor = '渡辺明乃', height = NULL, description = NULL WHERE character_id = 'CH003851';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b311040-Spi0OlKRCgMS.png', birthday = NULL, blood_type = NULL, voice_actor = '高梨謙吾', height = NULL, description = 'ウサトの同級生で、生徒会副会長。鈴音と同じように、英雄としてリングル王国に召喚され、光属性の魔法に才能がある。女子生徒からは絶大な人気を誇っているが、その一方で、男友達が一人もいないことに悩んでいる。' WHERE character_id = 'CH003852';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325576-EgcXrtbQzYY1.png', birthday = NULL, blood_type = NULL, voice_actor = '長縄まりあ', height = NULL, description = NULL WHERE character_id = 'CH003853';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b325584-5udK8137IPWs.png', birthday = '5月15日', blood_type = NULL, voice_actor = '青山吉能', height = NULL, description = NULL WHERE character_id = 'CH003854';
UPDATE characters SET image_url = 'https://s4.anilist.co/file/anilistcdn/character/large/b311041-D8ze3gkTkUGL.png', birthday = NULL, blood_type = NULL, voice_actor = '七瀬彩夏', height = NULL, description = '彼女は成績優秀で、スポーツも得意、誰もが憧れる生徒会長だ。彼女は英雄としてリングル王国に召喚され、雷属性の魔法の才能を持っている。 ウサトにとって、彼女はまるで高嶺の花のようだったが、異世界に召喚されてからは、次第に「本性」を見せ始めた。' WHERE character_id = 'CH003855';
